function resourceStrip(){const w=subjectWallet();return `<div class="subject-resource-strip" aria-label="과목별 배움 재료">${Resources.RESOURCE_SUBJECTS.map(subject=>{const resource=Resources.RESOURCE_TYPES[subject];return `<span><b>${resource.emoji} ${resource.name}</b><strong>${w.available[subject]}</strong></span>`;}).join('')}</div>`;}
const NATIVE_REWARDS=new Set(["star_yellow","star_blue","star_purple","star_rainbow","seed","sprout","bud","bloom","gift","heart","badge_book","badge_leaf","badge_crown","magic_dust"]);
function nativeRewardArt(id,className=''){
 if(!NATIVE_REWARDS.has(id))return '';
 const css=String(className).replace(/[^a-zA-Z0-9 _-]/g,'');
 return `<img class="native-art ${css}" src="./village/assets/${id}.png" alt="" aria-hidden="true" width="48" height="48" decoding="async" loading="lazy">`;
}
function nativeProgressArt(answered,total){
 if(!Number.isInteger(total)||total<=0)return 'seed';
 const count=Number.isFinite(answered)?Math.min(total,Math.max(0,Math.floor(answered))):0;
 return count===0?'seed':count>=total?'bloom':count/total<.5?'sprout':'bud';
}
function nativeStarArt(subject){
 return subject==='korean'?'star_purple':subject==='english'?'star_blue':'star_yellow';
}
function nativeGiftArt(item){
 const direct={'sun-spark':'star_yellow','ocean-stars':'star_blue','galaxy-glow':'star_purple','rainbow-orbit':'star_rainbow','mark-heart':'heart','mark-leaf':'sprout','mark-flower':'bloom'};
 return (Object.hasOwn(direct,item?.id)?direct[item.id]:'')||(item?.kind==='family'?'gift':'');
}
function nativeBadgeArt(badge){
 if(badge?.unlocked!==true)return 'seed';
 const earned={'first-round':'badge_leaf','three-subjects':'badge_book','try-again':'badge_crown','two-days':'star_rainbow'};
 return Object.hasOwn(earned,badge.id)?earned[badge.id]:'seed';
}
// Bebsu artwork is an independent math-learning companion, never a replacement
// for either child's fairy avatar. All paths are fixed, imported local assets.
const BEBSU_ART_ROOT='./assets/bebsu/art/';
function bebsuArt(file,alt='',className=''){
 if(!/^[a-z0-9_/-]+[.](?:webp|png)$/.test(file))return '';
 const css=String(className).replace(/[^a-zA-Z0-9 _-]/g,'');
 return `<img class="bebsu-art ${css}" src="${BEBSU_ART_ROOT}${file}" alt="${esc(alt)}" decoding="async" loading="lazy">`;
}
const isBebsuMath=()=>currentGame?.sourceGroup==='bebsu'&&currentGame?.subject==='math';
function bebsuCompanion(stage='ready'){
 const se=Progress.learner()==='se';
 const file=stage==='success'?(se?'states/pink-active-helper.webp':'states/brown-active-explorer.webp')
   :stage==='retry'?(se?'states/pink-ready-baby.webp':'states/brown-ready-helper.webp')
   :se?'states/pink-ready-helper.webp':'states/brown-ready-explorer.webp';
 return bebsuArt(file,stage==='success'?'기뻐하는 뱁수':stage==='retry'?'다시 함께 생각하는 뱁수':'수학을 돕는 뱁수','bebsu-companion-art');
}
function bebsuSuccessBadge(badge){
 if(badge?.unlocked!==true)return nativeRewardArt('seed');
 const art={'first-round':'badges/first-answer.png','try-again':'badges/review.png','two-days':'badges/steady.png'}[badge.id];
 return art?bebsuArt(art,'','bebsu-badge-art'):nativeRewardArt(nativeBadgeArt(badge));
}
function bebsuFeedbackScene(correct){
 const mood=correct?'icons/cheer.webp':'icons/lightbulb.webp';
 const message=correct?'다른 방법으로도 설명해 볼까?':'그림을 한 번 더 살펴봐도 좋아!';
 return `<div class="bebsu-feedback-scene">${bebsuArt(mood,'','bebsu-scene-art')}<strong>${message}</strong></div>`;
}
function nativeRoundCue(round){
 const total=round.ids.length,count=Math.min(total,round.answers.length);
 return `<span class="round-growth" data-stage="${nativeProgressArt(count,total)}">${nativeRewardArt(nativeProgressArt(count,total))}<span>답 ${count}/${total}</span></span>`;
}
const portrait=(who,extra='')=>`<span class="fairy-portrait ${who} ${extra}" role="img" aria-label="${who==='tae'?'태희의 분홍 별 요정':'세희의 연보라 달 요정'}"></span>`;
const buddyName=()=>Progress.learner()==='tae'?'분홍 별 요정':'연보라 달 요정';
function buddyMode(){const r=currentRound();if(view==='quiz'&&r?.finished)return 'finished';if(view==='quiz'&&r?.answers[r.index]&&!retrying)return r.answers[r.index].correct?'success':'retry';if(retryAnswer)return retryAnswer.correct?'success':'retry';return view==='quiz'?'thinking':'welcome';}
function buddy(){const look=wallet().look,who=Progress.learner(),r=currentRound(),a=r?.answers[r.index],mode=buddyMode();let text=companionMessage;if(!text){if(mode==='finished')text=who==='tae'?'오늘 발견한 것을 한 가지 들려줄래?':'오늘 마음은 어떤 그림이야?';else if(mode==='success')text=who==='tae'?'네가 고른 답을 확인했어. 어떤 방법이었는지 말해 볼까?':'네가 고른 답을 찾았구나!';else if(mode==='retry')text=who==='tae'?'다른 방법도 찾아보자. 다시 연습할 수 있어.':'괜찮아. 같이 다시 해보자.';else if(mode==='thinking')text=who==='tae'?'그림과 이야기를 보고 네 생각을 골라 줘.':'듣고, 그림을 보고, 하나씩 골라 봐.';else text=who==='tae'?'태희야, 오늘의 첫걸음을 골라 볼까?':'세희야, 오늘의 첫걸음을 골라 볼까?';}return `<aside class="companion-strip ${who} ${mode}"><div class="companion-portrait">${portrait(who)}<span class="fairy-name">${esc(look.title?.label||buddyName())}</span>${look.friend?`<span class="gift-friend" role="img" aria-label="${esc(look.friend.title)}">${look.friend.emoji}</span>`:''}${look.mark?`<span class="gift-mark" role="img" aria-label="${esc(look.mark.title)}">${nativeRewardArt(nativeGiftArt(look.mark))||look.mark.emoji}</span>`:''}${look.light?`<span class="gift-light" role="img" aria-label="${esc(look.light.title)}">${nativeRewardArt(nativeGiftArt(look.light))||look.light.emoji}</span>`:''}</div><div class="buddy-message"><small>${currentLearner().name}의 학습 친구</small><p id="buddy-message">${esc(text)}</p></div><button class="buddy-help" data-action="buddy-help" aria-label="요정에게 도움 받기">${view==='quiz'?'같이 보기':'인사하기'}<span aria-hidden="true">✦</span></button></aside>`;}
function positionMotion(){const box=document.querySelector('.companion-portrait')?.getBoundingClientRect(),host=document.querySelector('#motion-stage');if(box&&host){Object.assign(host.style,{left:box.left-12+'px',top:box.top-8+'px',width:box.width+24+'px',height:box.height+16+'px'});}}
function pages(total,size,current,action){const count=Math.max(1,Math.ceil(total/size));return `<div class="pager"><button class="secondary" data-action="${action}" data-direction="-1" ${current<=0?'disabled':''} aria-label="이전 페이지">이전</button><span aria-live="polite">${current+1} / ${count}</span><button class="secondary" data-action="${action}" data-direction="1" ${current>=count-1?'disabled':''} aria-label="다음 페이지">다음</button></div>`;}
try{const params=new URLSearchParams(location.search),requested=params.get('view'),who=params.get('who');if(who==='tae'||who==='se')Progress.selectLearner(who);if(['collection','workbooks','hanja'].includes(requested))view=requested;else if(requested==='parents')initialModal='parents';for(const key of [...params.keys()])if(!['view','who'].includes(key))params.delete(key);params.delete('view');params.delete('who');if(location.search)history.replaceState(history.state,'',location.pathname+location.hash);}catch{}
