function header(){const p=currentLearner(),w=wallet();return `<header class="header"><button class="brand" data-action="home" aria-label="반짝 배움터 처음으로"><span class="brand-star" aria-hidden="true">${nativeRewardArt('magic_dust')}</span><span><small>TAEHEE & SEHEE</small>반짝 배움터</span></button><nav class="nav" aria-label="주 메뉴">${[['home','놀이'],['workbooks','수학'],['hanja','한자'],['growth','성장'],['collection','별 선물']].map(([id,label])=>`<button data-action="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="user-controls"><button class="header-star" data-action="collection" aria-label="쓸 수 있는 별 ${w.available}개">${nativeRewardArt('star_yellow')} ${w.available}</button><button class="profile-button" data-action="profiles" aria-label="아이 바꾸기, 현재 ${p.name}">${portrait(Progress.learner(),'tiny')}${p.name}</button></div></header>`;}
function footer(){return `<footer class="footer"><span>내 속도로, 한 번의 발견씩 ✦</span><button data-action="parents">보호자 대시보드</button></footer>`;}
function missionLabel(mission){
 if(!mission)return '';
 const labels={review:['🔁','다시 떠올리기'],foundation:['🌱','내 힘으로 시작'],challenge:['🎯','알맞은 도전'],transfer:['🧭','다른 곳에 써보기']};
 const [icon,label]=labels[mission.kind]||['✨','오늘의 배움'];
 return `<div class="mission-tag ${mission.kind}"><span aria-hidden="true">${icon}</span><strong>${mission.order} · ${label}</strong></div><p class="mission-reason">${esc(mission.reason)}</p>`;
}
function gameCard(g,mission=null){const record=overview().games.find(r=>r.id===g.id);return `<article class="game-card ${g.subject} ${mission?'learning-mission':''}">${missionLabel(mission)}<div class="game-top"><div class="game-icon" aria-hidden="true">${g.sourceGroup==='bebsu'?bebsuArt(g.gradeBand==='K'?'icons/scholar.webp':'icons/abacus.webp','','bebsu-game-art'):esc(g.emoji)}</div><span class="subject-label">${SUBJECTS[g.subject].name} · ${esc(g.levelLabel)}</span></div><h3>${esc(g.title)}</h3><p class="game-desc">${esc(g.description)}</p><p class="mode-badges">${g.modes?g.modes.map(m=>esc(ActivityUI.MODE_LABELS[m])).join(' · '):'단위와 비율'}</p>${g.kind==='external'?`<a class="game-launch" href="${esc(g.url)}" data-external="${g.id}">${record.resume?'이어서 놀기':'놀러 가기'}</a>`:`<button class="game-launch" data-action="play" data-game="${g.id}" data-strategy="${mission?.strategy||'adaptive'}" data-purpose="${mission?.kind||''}" ${loading?'disabled':''}>${record.resume?'이어서 놀기':mission?.kind==='review'?'기억 꺼내기':'시작하기'}</button>`}<p class="game-progress">${record.started?`⭐ ${record.stars} · ${record.mastered}개의 발견`:`한 판 ${g.kind==='external'?5:currentLearner().roundSize}문제 · 천천히 해도 돼`}</p></article>`;}
function recommendedAdventures(){return ['math','korean','english'].flatMap(subject=>{const rec=Growth.recommendation(subject,catalog),stage=rec.canAdvance?rec.suggestedStage:rec.stage;let list=adventures().filter(g=>g.adventure&&g.subject===subject&&g.minStage<=stage&&g.maxStage>=stage);if(!list.length)list=adventures().filter(g=>g.adventure&&g.subject===subject&&g.minStage<=stage);list.sort((a,b)=>{const pa=Progress.gameProgress(a.id),pb=Progress.gameProgress(b.id);return Number(Boolean(pb.round&&!pb.round.finished))-Number(Boolean(pa.round&&!pa.round.finished))||pa.lastPlayed-pb.lastPlayed||a.id.localeCompare(b.id);});return list.length?[list[themeOffset%list.length]]:[];});}
function currentLearningPlan(subjectOverride=''){
 const goal=Progression.goal(Progress.learner()).id;
 const preferred=['math','korean','english'].includes(subjectOverride)?subjectOverride:['math','korean','english'].includes(goal)?goal:'';
 return LearningDirector.plan(catalog,{who:Progress.learner(),preferredSubject:preferred});
}
function home(){
 const plan=currentLearningPlan(filter);
 let items=showAll?adventures().map(game=>({game,mission:null})):plan.missions.map(mission=>({game:published().find(g=>g.id===mission.gameId),mission})).filter(item=>item.game);
 items=items.filter(({game})=>(filter==='all'||game.subject===filter)&&(modeFilter==='all'||!showAll||game.modes?.includes(modeFilter)));
 const size=pageSize();page=Math.min(page,Math.max(0,Math.ceil(items.length/size)-1));const w=wallet(),next=AWARDS.find(a=>a.stars>w.lifetime);
 return `<section class="home-screen screen"><div class="section-top"><div><h1 tabindex="-1">${currentLearner().name}의 ${showAll?'놀이 보물지도':'오늘의 3걸음'}</h1><p class="place-line">${showAll?'🏡 '+esc(Settings.getSettings()[Progress.learner()].place)+'에서 이어지는 놀이':'🧠 '+esc(plan.principle)+' · 하나부터 시작해도 좋아요.'}</p></div><button class="text-button" data-action="all-games">${showAll?'오늘의 3걸음':'모두 보기'}</button></div><div class="filters" aria-label="과목 고르기">${Object.entries(SUBJECTS).map(([id,s])=>`<button class="filter" data-action="filter" data-subject="${id}" aria-pressed="${filter===id}">${s.emoji} ${s.name}</button>`).join('')}</div>${showAll?`<div class="mode-select"><label for="mode-select">놀이 방법</label><select id="mode-select">${[['all','모든 놀이'],...Object.entries(ActivityUI.MODE_LABELS).filter(([id])=>adventures().some(g=>g.modes?.includes(id)))].map(([id,label])=>`<option value="${id}" ${modeFilter===id?'selected':''}>${label}</option>`).join('')}</select><span>${items.length}가지</span></div>`:`<aside class="learning-loop-note"><strong>오늘의 원칙</strong><span>힌트 없이 먼저 떠올리고 → 내 수준에 맞게 도전하고 → 다른 이야기에서 다시 써봐요.</span></aside>`}<div class="games-grid">${items.slice(page*size,(page+1)*size).map(({game,mission})=>gameCard(game,mission)).join('')||'<p class="empty">다른 과목을 골라 보거나 전체 놀이를 살펴봐!</p>'}</div><div class="home-tools">${pages(items.length,size,page,'game-page')}<button class="secondary" data-action="growth">성장 정원 보기</button></div>${resourceStrip()}<button class="reward-preview-link" data-action="collection"><span>⭐ 모은 별 ${w.lifetime} · 쓸 수 있는 별 ${w.available}</span><span>${next?`다음 별자리: ${next.name}`:'내 별자리가 반짝여!'}</span></button><section class="home-villages" aria-labelledby="home-village-title"><div class="home-villages-heading"><h2 id="home-village-title">마법마을 모험</h2><p>복습·도전·전이를 마치면 마을의 변화도 오래 남아요.</p></div><div class="home-village-grid"><a class="village-launch village-launch-bebsu" href="./village/" aria-label="통합 마법마을로 돌아가기"><span class="village-launch-icon" aria-hidden="true">🧚</span><span class="village-launch-copy"><strong>하나의 통합 마법마을로 돌아가기</strong><small>배운 것을 다시 꺼내고, 적용하고, 꽃과 나무를 키워요.</small></span><span class="village-launch-arrow" aria-hidden="true">↗</span></a></div></section></section>`;
}
function workbookHome(){const banks=workbooks(),available=BOOK_GRADES.filter(([id])=>banks.some(g=>g.gradeBand===id)),who=Progress.learner();if(!available.some(([id])=>id===bookGrades[who]))bookGrades[who]=available[0]?.[0];const grade=bookGrades[who],games=banks.filter(g=>g.gradeBand===grade),size=pageSize(),suggestion=Progress.workbookSuggestion(grade);bookPage=Math.min(bookPage,Math.max(0,Math.ceil(games.length/size)-1));return `<section class="screen workbook-screen"><div class="section-top"><h1 tabindex="-1">${currentLearner().name}의 뱁수 수학 문제집</h1><span class="book-mark" aria-hidden="true">${bebsuArt('icons/scholar.webp','','bebsu-book-mark')}</span></div>${available.length?`<div class="bebsu-study-banner">${bebsuCompanion()}<div class="bebsu-banner-copy"><strong>뱁수 수학 연구소</strong><p>한 문제씩 차근차근, 내 방법으로 풀어 보자!</p></div>${bebsuArt('icons/abacus.webp','','bebsu-banner-tool')}</div><div class="grade-select"><label for="grade-select">학년 고르기</label><select id="grade-select">${available.map(([id,label])=>`<option value="${id}" ${grade===id?'selected':''}>${label}</option>`).join('')}</select><span>${games.length}권</span></div><p class="book-intro">내가 풀어 보고 싶은 문제집을 골라요. 다른 학년도 어른과 함께 살펴볼 수 있어요.</p>${suggestion?`<p class="workbook-suggestion">서로 다른 ${suggestion.distinct}문제를 꾸준히 풀었어요. 보호자와 함께 ${esc(BOOK_GRADES.find(([id])=>id===suggestion.next)?.[1])}에 도전해 볼까요? <button class="secondary" data-action="suggested-grade" data-grade="${suggestion.next}">다음 문제집 보기</button></p>`:''}<div class="games-grid">${games.slice(bookPage*size,(bookPage+1)*size).map(gameCard).join('')}</div>${pages(games.length,size,bookPage,'book-page')}`:'<p class="empty">수학 문제집을 준비하고 있어요. 오늘의 모험부터 만나 볼까요?</p><button class="primary" data-action="home">오늘의 모험</button>'}<p class="note">별은 함께 모이고, 성장 지도는 기초 놀이의 기록으로 이어져요.</p></section>`;}
function hanjaHome(){return HanjaUI.renderHanjaHome({catalog,who:Progress.learner(),selected:hanjaGrades[Progress.learner()],flipped:hanjaShown});}
const imagePath=(q,kind)=>{const path=q?.[kind==='solution'?'solutionImage':'problemImage'];return typeof path==='string'&&/^\.\/assets\/bebsu\/math\/[a-f0-9]{16}\.png$/.test(path)?path:null;};
function sourceImageLabel(q,kind){const recovery=q.provenance?.[kind==='solution'?'solutionImage':'problemImage']?.recovery,number=q.provenance?.examQuestionNo;return recovery?.method?.includes('page_fallback')?`원본 ${kind==='solution'?'자료':'문제'}${Number.isInteger(number)?' · '+number+'번 확인':''}`:kind==='solution'?'원본 풀이':'원본 문제';}
function sourceImage(q,kind){const path=imagePath(q,kind);if(!path)return '';const label=sourceImageLabel(q,kind);return `<figure class="source-figure"><button class="source-preview" data-action="image-open" data-image-kind="${kind}" aria-label="${label} 크게 보기"><img src="${path}" alt="${esc(q.title)} ${label} 그림"><span>${label} 크게 보기 ↗</span></button></figure>`;}
function explanationPages(q){return [...(compactQuestion()?[{kind:'answer',text:answerText(q)}]:[]),...q.explanation.map(text=>({kind:'text',text})),...(imagePath(q,'solution')?[{kind:'solution',text:`${sourceImageLabel(q,'solution')} 그림을 크게 열어서 해당 문항을 확인해 봐요.`}]:[])];}
function growth(){
 const subject=growthSubject,rec=Growth.recommendation(subject,catalog),size=window.innerWidth<700?2:4,nurture=Progression.snapshot(catalog,Progress.learner()),goal=nurture.goal;
 growthPage=Math.min(growthPage,Math.ceil(4/size)-1);
 const pct=Math.round(nurture.rankProgress*100),nextLabel=nurture.next?`${nurture.next.emoji} ${nurture.next.name}`:'지금의 마을';
 return `<section class="screen growth-screen">
 <div class="section-top"><div><h1 tabindex="-1">${currentLearner().name}의 성장 정원</h1><p class="place-line">요정과 마을은 조금씩 여러 모습으로 자라요.</p></div><button class="text-button" data-action="growth-evidence">보호자와 기록 보기</button></div>
 <section class="growth-hero" aria-label="${currentLearner().name}의 마을 육성 현황">
   <div class="growth-avatar"><div class="growth-orbit" style="--growth-progress:${pct}%">${portrait(Progress.learner(),'growth')}</div><span class="growth-rank-chip">✨ 나의 마을</span></div>
   <div class="growth-hero-copy"><small>지금의 마을 모습</small><h2>${nurture.rank.emoji} ${esc(nurture.rank.name)}</h2><p>${nurture.next?`${esc(nextLabel)}도 언젠가 만나 볼 수 있어요.`:'지금의 마을을 충분히 즐겨요.'}</p><div class="growth-meter" role="progressbar" aria-label="다음 마을 모습까지" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><span style="width:${pct}%"></span></div><small>${nurture.next?'조금씩 자라는 중이에요':'즐겁게 가꾸는 중이에요'}</small></div>
   <div class="growth-metrics">
     <div><strong>${nurture.mastered}</strong><span>발견한 문항</span></div>
     <div><strong>${nurture.rounds}</strong><span>완료 모험</span></div>
     <div><strong>${nurture.flowers}</strong><span>피어난 꽃</span></div>
     <div><strong>${nurture.stars}</strong><span>모은 별</span></div>
   </div>
 </section>
 <section class="growth-goal-panel" aria-labelledby="growth-goal-title"><div class="growth-goal-head"><div><small>내가 고르는 육성 방향</small><h2 id="growth-goal-title">${goal.emoji} ${esc(goal.name)}</h2></div><p>${esc(goal.description)}</p></div><div class="growth-goals">${Object.values(Progression.GOALS).map(item=>`<button data-action="growth-goal" data-goal="${item.id}" aria-pressed="${goal.id===item.id}"><span aria-hidden="true">${item.emoji}</span><strong>${esc(item.name)}</strong></button>`).join('')}</div></section>
 <div class="filters" aria-label="성장 지도 과목">${['math','korean','english'].map(id=>`<button class="filter" data-action="growth-subject" data-subject="${id}" aria-pressed="${subject===id}">${SUBJECTS[id].emoji} ${SUBJECTS[id].name}</button>`).join('')}</div>
 <p class="map-intro">지금의 배움 길은 ${Growth.STAGES[rec.stage].emoji} ${Growth.STAGES[rec.stage].name}. 풀어 본 내용을 참고해 다음 놀이를 골라요.</p>
 <div class="growth-path">${[1,2,3,4].slice(growthPage*size,(growthPage+1)*size).map(stage=>{const st=Growth.STAGES[stage],g=published().find(g=>g.growth&&g.subject===subject&&g.stage===stage);return g?`<article class="stage-node ${stage===rec.stage?'selected':''}"><span class="stage-icon" aria-hidden="true">${st.emoji}</span><h2>${esc(st.name)}</h2><p>${esc(g.description)}</p><button class="secondary" data-action="stage" data-subject="${subject}" data-stage="${stage}">${stage===rec.stage?'이어 배우기':'골라 보기'}</button></article>`:'';}).join('')}</div>
 ${size<4?pages(4,size,growthPage,'growth-page'):''}<p class="growth-reason">잘 맞는 문제부터 천천히 만나 보고, 어려우면 잠깐 쉬어도 좋아요.</p>
 <p class="irt-evidence">배우는 속도는 모두 달라요. 다음에 다시 생각해 볼 내용은 보호자와 함께 확인할 수 있어요.</p>
 ${adaptiveNotice?`<p class="note">${esc(adaptiveNotice)}</p>`:''}<p class="note">마을의 모습은 재미로 자라요. 아이의 능력이나 가치를 평가하는 표시가 아니에요.</p>
 </section>`;
}
function picture(q){const v=q.visual;if(!v)return '';
 if(v.kind==='groups')return `<div class="question-picture groups-picture" style="--group-count:${v.groups.length}">${v.groups.map(g=>`<div class="group-box"><p>${esc(g.label)}</p><div class="counter-group" role="img" aria-label="${esc(g.label)} ${g.count}개">${Array.from({length:g.count},()=>`<span aria-hidden="true">${esc(g.emoji)}</span>`).join('')}</div></div>`).join('')}</div>`;
 if(v.kind==='bars'){const max=Math.max(...v.bars.map(b=>b.value));return `<div class="question-picture bars-picture">${v.bars.map(b=>`<div><p>${esc(b.label)}</p><div class="measure-track"><span style="width:${b.value/max*100}%;background:${b.label.includes('분홍')?'#d967a1':b.label.includes('노란')?'#e5b638':b.label.includes('초록')?'#519f69':'#a986d4'}"></span></div></div>`).join('')}</div>`;}
 if(v.kind==='fraction')return `<div class="question-picture"><p class="fraction-label">${esc(v.label)}</p><div class="fraction-bar" role="img" aria-label="똑같이 나눈 ${v.parts}조각 중 색칠한 ${v.filled}조각">${Array.from({length:v.parts},(_,i)=>`<span class="${i<v.filled?'filled':''}"></span>`).join('')}</div></div>`;
if(v.kind==='counters'){
 if(v.operator==='-')return `<div class="question-picture"><div class="counter-group" style="margin:auto;max-width:440px" role="img" aria-label="${v.left}개 중 ${v.right}개를 빼는 그림">${Array.from({length:v.left},(_,i)=>`<span style="${i>=v.left-v.right?'opacity:.28;text-decoration:line-through;text-decoration-color:#715384':''}">${esc(v.emoji)}</span>`).join('')}</div><p class="counter-caption">처음 ${v.left}개에서 ${v.right}개를 빼 보자.</p></div>`;
 return `<div class="question-picture"><div class="counters" role="img" aria-label="${v.left}개와 ${v.right}개를 합치는 그림"><div class="counter-group">${Array.from({length:v.left},()=>`<span>${esc(v.emoji)}</span>`).join('')}</div><span class="operator">+</span><div class="counter-group">${Array.from({length:v.right},()=>`<span>${esc(v.emoji)}</span>`).join('')}</div></div><p class="counter-caption">두 무리를 하나씩 세어 보자.</p></div>`;
 }return `<div class="question-picture"><span class="${v.kind==='word'?'visual-word':'picture-emoji'}" ${v.kind==='emoji'?'aria-hidden="true"':''}>${esc(v.kind==='word'?v.text:v.emoji)}</span></div>`;}
function quiz(){
 const r=currentRound();if(!r)return '<section class="error"><h1>하던 놀이를 찾지 못했어요.</h1><button class="primary" data-action="home">놀이 고르기</button></section>';if(r.finished)return result();
 const q=currentQuestion();if(!q)return '<section class="error"><h1>놀이를 다시 골라 주세요.</h1><button class="primary" data-action="home">놀이 고르기</button></section>';
 const compact=compactQuestion(),key=r.id+':'+q.id+':'+retrying;if(key!==questionPaneKey){questionPaneKey=key;questionPane=retrying?'play':'story';}
 const saved=r.answers[r.index],a=retrying?retryAnswer:saved;
 const cue=q.cue?`<button class="cue-button" data-action="cue">🔊 소리 듣기</button><span class="cue-fallback">${esc(q.cue.text)}</span>`:'';
 const intro=compact&&questionPane==='story';
 const question=`<section class="panel question-panel ${compact?'paged-question':''} ${imagePath(q,'problem')?'source-question':''}" data-question-pane="${intro?'story':'play'}"><div class="question-head"><div><p class="question-type">${isBebsuMath()?bebsuArt('icons/think.webp','','bebsu-inline-art'):SUBJECTS[currentGame.subject].emoji} ${q.interaction?esc(ActivityUI.MODE_LABELS[q.interaction.type]):'생각해요'}</p><h1 tabindex="-1">${esc(q.title)}</h1></div>${compact&&!intro?(imagePath(q,'problem')?'<button class="secondary story-toggle" data-action="image-open" data-image-kind="problem">문제 그림</button>':'<button class="secondary story-toggle" data-action="question-story">이야기</button>'):''}${'speechSynthesis'in window?`<button class="sound" data-action="read" aria-label="${imagePath(q,'problem')?'문제 그림 안내와 보기 읽어주기':'문제와 보기 읽어주기'}">🔊</button>`:''}</div>${intro?`<div class="question-body story-page"><p class="story">${esc(q.story)}</p>${sourceImage(q,'problem')}${!q.interaction||q.interaction.type==='numeric'?picture(q):''}${cue}${q.interaction?`<h2 class="prompt">${esc(q.prompt)}</h2>`:''}</div><button class="primary question-play" data-action="question-play">내 생각으로 해 볼래!</button>`:`${compact?(!q.interaction?`<div class="question-body"><h2 class="prompt">${esc(q.prompt)}</h2>${cue}</div>`:''):`<div class="question-body"><p class="story">${esc(q.story)}</p>${sourceImage(q,'problem')}${!q.interaction||q.interaction.type==='numeric'?picture(q):''}${cue}<h2 class="prompt">${esc(q.prompt)}</h2></div>`}${currentGame.subject==='hanja'&&!intro?`<div class="hanja-play-glyph" aria-label="한자 ${esc(q.hanjaCharacter)}">${esc(q.hanjaCharacter)}</div>`:''}<div class="activity-zone">${ActivityUI.renderActivity(q,null,activityDraft(q),esc)}</div>`}<p class="voice-status" id="voice-status" role="status"></p></section>`;
 return `<div class="game-area screen"><div class="activity-head"><button class="back" data-action="${currentGame.sourceGroup==='bebsu'?'workbooks':currentGame.subject==='hanja'?'hanja':'home'}">잠깐 쉬기</button><span class="activity-title">${esc(currentGame.title)}${retrying?' · 다시 연습':''}</span><span>${r.index+1} / ${r.ids.length}</span></div><div class="round-progress"><div class="steps" aria-label="${r.ids.length}문제 중 ${r.index+1}번째">${Array.from({length:r.ids.length},(_,i)=>`<span class="step ${i<r.index?'done':i===r.index?'current':''}"></span>`).join('')}</div>${nativeRoundCue(r)}<span class="round-earned">${nativeRewardArt(nativeStarArt(currentGame.subject))} +${r.answers.reduce((n,a)=>n+a.earned,0)}</span></div>${a?feedback(q,a,r):question}</div>`;
}
function feedback(q,a,r){
 const compact=compactQuestion(),pages=explanationPages(q),count=pages.length;explainIndex=Math.min(explainIndex,count-1);const item=pages[explainIndex],answerPage=item.kind==='answer',imagePage=item.kind==='solution';
 return `<section class="panel feedback-panel ${a.correct?'success':'learn'} ${compact?'paged-feedback':''}" id="feedback" tabindex="-1"><div class="feedback-head"><h1 tabindex="-1">${a.correct?'✨ 발견했어!':'🌱 함께 알아보자!'}</h1>${isBebsuMath()?bebsuCompanion(a.correct?'success':'retry'):''}<span class="earned">${(retrying?a.effortEarned:a.earned)>0?nativeRewardArt(nativeStarArt(currentGame.subject)):''}${retrying?(a.effortEarned?`⭐ 노력 +${a.effortEarned}`:'다시 연습'):a.earned?`⭐ 기존 별 +${a.earned}`:'복습 완료'}</span>${!retrying&&lastResourceGain&&Resources.RESOURCE_SUBJECTS.some(s=>lastResourceGain[s]>0)?`<strong class="subject-resource-earned">${Resources.RESOURCE_SUBJECTS.filter(s=>lastResourceGain[s]>0).map(s=>Resources.RESOURCE_TYPES[s].emoji+' '+Resources.RESOURCE_TYPES[s].name+' +'+lastResourceGain[s]).join(' · ')}</strong>`:''}</div>${compact?'':`<div class="correct-answer" ${currentGame.subject==='english'?'lang="en"':''}>${esc(answerText(q))}</div>`}<div class="explanation-page ${answerPage?'answer-page':''} ${imagePage?'solution-page':''}">${isBebsuMath()&&!imagePage?bebsuFeedbackScene(a):''}${imagePage?sourceImage(q,'solution'):`<p ${answerPage&&currentGame.subject==='english'?'lang="en"':''}>${esc(item.text)}</p>`}<span>${answerPage?'찾은 답':imagePage?'원본 풀이':'풀이'} ${explainIndex+1} / ${count}</span></div><div class="feedback-tools"><button class="secondary" data-action="explain-prev" ${explainIndex===0?'disabled':''}>앞 풀이</button><button class="secondary" data-action="explain">🔊 듣기</button><button class="secondary" data-action="explain-next" ${explainIndex===count-1?'disabled':''}>다음 풀이</button></div><div class="feedback-actions">${!retrying||!a.correct?'<button class="secondary" data-action="retry">내가 다시 풀기</button>':''}${q.speak?'<button class="secondary" data-action="pronounce">영어로 듣기</button>':''}<button class="primary" data-action="next">${r.index===r.ids.length-1?'한 판 마치기':'다음 이야기'}</button></div><p class="voice-status" id="voice-status" role="status"></p></section>`;
}
function teachBackPrompt(){
 if(learningPurpose==='review')return '방금 다시 떠올린 방법을 화면을 보지 않고 한 문장으로 말해 볼까?';
 if(learningPurpose==='transfer')return '방금 쓴 방법을 다른 물건이나 이야기에서 어디에 또 쓸 수 있을까?';
 if(learningPurpose==='challenge')return '가장 생각이 많이 필요했던 한 문제를 골라, 왜 그렇게 풀었는지 설명해 볼까?';
 if(learningPurpose==='foundation')return '오늘 처음 발견한 것을 하나 골라 내 말로 설명해 볼까?';
 return REFLECTIONS[currentGame.subject];
}
function result(){const r=currentRound(),stars=r.answers.reduce((n,a)=>n+a.earned,0);return `<div class="game-area screen"><section class="panel result"><div class="result-icon" aria-hidden="true">${isBebsuMath()?bebsuCompanion('success'):nativeRewardArt('bloom')}</div><h1 tabindex="-1">${currentLearner().name}의 발견이 늘었어!</h1><p>${r.ids.length}개의 이야기를 끝까지 만났네.</p><div class="result-stats"><div class="stat"><strong>⭐ +${stars}</strong><span>문제에서 모은 별</span></div><div class="stat"><strong>💬 나의 생각</strong><span>어떤 방법을 썼는지 이야기해 봐요</span></div></div><div class="conversation teach-back"><small>내 말로 다시 설명하기</small>${esc(teachBackPrompt())}</div>${currentGame.offline?`<div class="conversation"><small>화면 밖에서도 놀자!</small>${esc(currentGame.offline)}</div>`:''}<div class="reflection-choices" aria-label="오늘의 발견 돌아보기"><button class="secondary" data-action="reflection" data-reflection="발견">💡 새로 알았어</button><button class="secondary" data-action="reflection" data-reflection="재도전">🌱 다시 해 볼래</button><button class="secondary" data-action="reflection" data-reflection="이야기">💬 이야기했어</button></div>${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}<button class="primary" data-action="collection">별 선물 고르기</button><button class="text-button" data-action="${currentGame.subject==='hanja'?'hanja':'home'}">${currentGame.subject==='hanja'?'📜 한자 수련관으로 돌아가기':'쉬거나 다른 놀이 고르기'}</button></section></div>`;}
function collection(){const w=wallet(),tabs=[['rewards','선물 고르기'],['badges','성공 이야기'],['records','놀이 기록']];let content='';if(collectionTab==='rewards'){const items=w.items.filter(item=>(rewardCategory==='all'||item.category===rewardCategory)&&(rewardFilter==='all'||(rewardFilter==='owned'?item.owned:item.canPurchase))),size=pageSize();collectionPage=Math.min(collectionPage,Math.max(0,Math.ceil(items.length/size)-1));content=`<div class="gift-controls"><label for="gift-category">종류<select id="gift-category">${[['all','🎁 전체'],...Rewards.REWARD_CATEGORIES.map(c=>[c.id,c.emoji+' '+c.title])].map(([id,label])=>`<option value="${id}" ${rewardCategory===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label for="gift-filter">보기<select id="gift-filter">${[['all','모든 선물'],['affordable','지금 고를 선물'],['owned','내 선물']].map(([id,label])=>`<option value="${id}" ${rewardFilter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="gift-summary"><div class="gift-count" role="status">${items.length}가지${rewardCategory==='all'&&rewardFilter==='all'?' · 원하는 종류를 골라 봐!':''}</div><button class="text-button" data-action="wardrobe">함께하는 선물 ${Object.values(w.look).filter(Boolean).length}</button></div><div class="reward-grid">${items.length?items.slice(collectionPage*size,(collectionPage+1)*size).map(item=>`<article class="reward-card ${item.equipped?'wearing':''}"><div class="reward-symbol" aria-hidden="true">${nativeRewardArt(nativeGiftArt(item))||item.emoji}</div><h2>${esc(item.title)}</h2><p>${esc(item.description|| (item.kind==='family'?'어른과 날짜를 정해서 함께해요.':'요정 친구를 꾸며요.'))}</p><span class="reward-cost">⭐ ${item.cost}</span><button class="primary" data-action="reward" data-reward="${item.id}" ${item.equipped||item.pending||(!item.owned&&w.available<item.cost)?'disabled':''}>${item.owned?(item.equipped?'함께하고 있어':'이 선물 쓰기'):(item.pending?'신청했어요':item.kind==='family'?`별 ${item.cost}개로 신청`:'이 선물 고르기')}</button></article>`).join(''):`<p class="empty gift-empty">${rewardFilter==='owned'?'아직 고른 선물이 없어. 다른 보기에서 마음에 드는 선물을 찾아봐!':'다른 종류를 골라 볼까? 별을 조금씩 모아도 괜찮아.'}</p>`}</div>${items.length?pages(items.length,size,collectionPage,'collection-page'):''}<p class="note">꾸미기 선물은 한 번 고르면 내 선물이야. 바꿔 써도 별은 그대로! 가족 활동은 어른과 의논해요.</p>`;}else if(collectionTab==='badges'){const badges=w.badges,size=window.innerWidth<700?2:4;collectionPage=Math.min(collectionPage,Math.max(0,Math.ceil(badges.length/size)-1));content=`<div class="success-grid">${badges.slice(collectionPage*size,(collectionPage+1)*size).map(b=>`<article class="success-card ${b.unlocked?'':'locked'}"><span aria-hidden="true">${bebsuSuccessBadge(b)}</span><h2>${esc(b.title)}</h2><p>${esc(b.description||b.reason||'배운 과정이 쌓이면 만나요.')}</p><small>${b.unlocked?'내가 해냈어!':'차근차근 만나자'}</small></article>`).join('')}</div>${pages(badges.length,size,collectionPage,'collection-page')}<div class="milestone-strip">${AWARDS.map(a=>`<span class="${w.lifetime>=a.stars?'unlocked':''}">${nativeRewardArt(w.lifetime>=a.stars?(a.stars===30?'sprout':a.stars===100?'bloom':a.stars===250?'star_rainbow':'badge_crown'):'seed')} ${a.name}<small>누적 ${a.stars}</small></span>`).join('')}</div><p class="note">배지는 실제 풀이에서 만나요. 별 개수로 학습 단계를 올리지 않아요.</p>`;}else{const records=overview().games.filter(g=>g.started>0),size=window.innerWidth<700?(window.innerHeight<740?2:4):(window.innerHeight<820?4:5);collectionPage=Math.min(collectionPage,Math.max(0,Math.ceil(records.length/size)-1));content=`<section class="panel records-panel">${records.slice(collectionPage*size,(collectionPage+1)*size).map(r=>{const g=published().find(g=>g.id===r.id);return `<div class="record-row"><span>${esc(g.emoji)} ${esc(g.title)}</span><span>${r.mastered}개의 발견</span><span>⭐ ${r.stars}</span></div>`;}).join('')||'<p class="empty">첫 모험에서 발견을 모아 볼까?</p>'}</section>${pages(records.length,size,collectionPage,'collection-page')}<p class="note">단위 정원의 별도 함께 보여요. 같은 기기·브라우저에서 이어져요.</p>`;}return `<section class="screen collection-screen"><div class="section-top"><h1 tabindex="-1">${currentLearner().name}의 별 보물함</h1><button class="text-button" data-action="parents">가족 신청 확인</button></div>${resourceStrip()}<p class="legacy-star-note">과목별 자원으로 연못 친구와 새 마을 시설을 만나요. 기존 별은 이전 선물에 계속 사용할 수 있습니다.</p><div class="wallet-stats"><div><strong>⭐ ${w.available}</strong><span>쓸 수 있는 별</span></div><div><strong>${w.lifetime}</strong><span>평생 모은 별</span></div><div><strong>${w.spent}</strong><span>선물로 바꾼 별</span></div></div><div class="collection-tabs">${tabs.map(([id,label])=>`<button class="filter" data-action="collection-tab" data-tab="${id}" aria-pressed="${collectionTab===id}">${label}</button>`).join('')}</div>${notice?`<p class="notice" role="status">${esc(notice)}</p>`:''}${content}</section>`;}
function render(){Rewards.syncRewards(catalog,Progress.learner());CloudSync.scheduleSync();document.body.dataset.learner=Progress.learner();document.body.dataset.view=view;const colors=wallet().look.background?.colors;document.body.style.setProperty('--gift-background',colors?'linear-gradient(145deg,'+colors.join(',')+')':'none');const content=error?`<section class="error"><h1 tabindex="-1">잠깐, 놀이를 확인할게.</h1><p>${esc(error)}</p><button class="primary" data-action="reload">다시 불러오기</button><button class="text-button" data-action="home">배움터로</button></section>`:view==='home'?home():view==='collection'?collection():view==='growth'?growth():view==='workbooks'?workbookHome():view==='hanja'?hanjaHome():quiz();app.innerHTML=header()+`<main class="shell" id="main">${setupNotice?`<div class="storage-warning" role="status">${esc(setupNotice)}</div>`:''}${!Progress.storageAvailable||!Settings.storageAvailable()||!Rewards.rewardStorageAvailable()?'<div class="storage-warning" role="status">지금은 기록이 저장되지 않을 수 있어요. 보호자 안내에서 기록을 내보내 주세요.</div>':''}${buddy()}${content}</main>`+footer();motion.update({who:Progress.learner(),mode:buddyMode(),equipped:wallet().equipped,effect:wallet().look.light?.effect||{}});requestAnimationFrame(positionMotion);}
async function launch(id,strategy='adaptive',purpose=''){const entry=published().find(g=>g.id===id);if(!entry||entry.kind!=='quiz')throw new Error('시작할 놀이를 선택해 주세요.');const generation=++loadGeneration;const who=Progress.learner();loading=true;error='';render();document.querySelector('#announcer').textContent='놀이를 불러오고 있어요.';try{const game=await loadGame(entry);if(generation!==loadGeneration||who!==Progress.learner())return;companionMessage='';explainIndex=0;retrying=false;retryAnswer=null;currentGame={...game,title:entry.title,sourceGroup:entry.sourceGroup,gradeBand:entry.gradeBand};roundOwner=who;learningPurpose=purpose;const rec=Growth.recommendation(entry.subject,catalog);Progress.beginRound(currentGame,{level:rec.canAdvance?rec.suggestedStage:rec.stage,strategy,purpose});view='quiz';stopSound();render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('main h1')?.focus({preventScroll:true});}catch(e){if(generation===loadGeneration){error=e.message;render();}}finally{if(generation===loadGeneration)loading=false;}return{game:id,view};}
function answer(response){if(view!=='quiz'||!currentGame)return;if(roundOwner!==Progress.learner()){move('home');return;}let a;if(retrying){if(retryAnswer)return;a=gradeResponse(currentQuestion(),response);retryAnswer=a;if(a.correct){const effort=Rewards.recordEffort({who:Progress.learner(),eventId:'retry-'+currentRound().id+'-'+currentQuestion().id,kind:'retry',gameId:currentGame.id,questionId:currentQuestion().id});retryAnswer.effortEarned=effort.earned;}}else{const before=subjectWallet().available;a=Progress.answerQuestion(currentGame,response);if(a){const after=subjectWallet().available;lastResourceGain=Object.fromEntries(Resources.RESOURCE_SUBJECTS.map(s=>[s,Math.max(0,after[s]-before[s])]));}}if(!a)return;companionMessage='';explainIndex=0;stopSound();render();motion.burst(a.correct?'success':'retry');document.querySelector('#feedback')?.focus({preventScroll:true});document.querySelector('#announcer').textContent=a.correct?'답을 찾았어요. 풀이를 확인해 봐요.':'해설과 함께 알아봐요.';}
function speak(mode='question'){const q=currentQuestion();if(!q||!('speechSynthesis'in window))return;const answered=currentRound()?.answers[currentRound().index];if(['answer','explain'].includes(mode)&&!answered)return;stopSound();let parts=[];if(mode==='answer'&&q.speak)parts=[q.speak];else if(mode==='cue'&&q.cue)parts=[q.cue];else if(mode==='explain')parts=[{text:personal(explanationPages(q)[explainIndex]?.text||'풀이를 다시 확인해 봐요.'),lang:'ko-KR'}];else {parts=[{text:personal(q.readText||q.story+' '+q.prompt),lang:'ko-KR'}];if(q.cue)parts.push(q.cue);if(!q.readText)(q.choices||q.interaction?.items||q.interaction?.left||[]).forEach((c,i)=>{parts.push({text:`${i+1}번.`,lang:'ko-KR'},{text:q.choiceLabels?.[i]||q.interaction?.itemLabels?.[i]||c,lang:(q.choiceLabels||q.interaction?.itemLabels)?'ko-KR':currentGame.subject==='english'?'en-US':'ko-KR'});});}for(const part of parts){const u=new SpeechSynthesisUtterance(personal(part.text));u.lang=part.lang;u.rate=part.lang==='en-US'?0.72:0.82;u.onerror=()=>{const el=document.querySelector('#voice-status');if(el)el.textContent='음성이 들리지 않으면 어른이 문제와 보기를 읽어 주세요.';};window.speechSynthesis.speak(u);}}
const parentEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parentPct=value=>value===null||value===undefined?'—':Math.round(value*100)+'%';
function parentDueText(at,now){if(!Number.isFinite(at))return '예정 없음';const d=at-now;if(d<=0)return '지금';if(d<24*60*60*1000)return '오늘';return Math.max(1,Math.ceil(d/(24*60*60*1000)))+'일 후';}
