document.addEventListener('change',async e=>{if(['gift-category','gift-filter'].includes(e.target.id)){const id=e.target.id,value=e.target.value;if(id==='gift-category')rewardCategory=value;else rewardFilter=value;collectionPage=0;render();document.getElementById(id)?.focus({preventScroll:true});return;}if(e.target.id==='grade-select'){if(BOOK_GRADES.some(([id])=>id===e.target.value)){bookGrades[Progress.learner()]=e.target.value;bookPage=0;render();document.querySelector('#grade-select')?.focus({preventScroll:true});}return;}if(e.target.id==='mode-select'){modeFilter=e.target.value;page=0;render();return;}if(e.target.id!=='import-file'||!e.target.files[0])return;const status=document.querySelector('#import-status');try{if(e.target.files[0].size>10000000)throw new Error('파일이 너무 커요. 배움터에서 내보낸 10MB 이하 기록을 선택해 주세요.');const raw=JSON.parse(await e.target.files[0].text());const family=raw.familySettings?Settings.validateSettings(raw.familySettings):null;const balance=raw.playBalance?PlayBalance.validateBalance(raw.playBalance):null;Progress.importRecords(raw);if(raw.rewards)Rewards.importRewards(raw.rewards);if(family)Settings.saveSettings(family);if(raw.village)VillageState.saveVillage(VillageState.mergeVillage(VillageState.loadVillage(),raw.village));if(raw.growthGoals)Progression.importGoals(raw.growthGoals);if(raw.relationships)RelationshipState.importRelationships(raw.relationships);if(raw.ecology)EcologyState.importEcology(raw.ecology);if(raw.resources)Resources.importResources(raw.resources);if(raw.career)Careers.importCareer(raw.career);if(balance)PlayBalance.importBalance(balance);render();app.inert=Boolean(modal);const freshStatus=document.querySelector("#import-status");if(freshStatus?.isConnected)freshStatus.textContent='기록을 합쳤어요. 원래 모은 별도 그대로예요.';}catch(error){if(status?.isConnected)status.textContent='가져오지 못했어요. '+(error instanceof SyntaxError?'올바른 JSON 기록 파일을 골라 주세요.':error.message);}e.target.value='';});
document.addEventListener('keydown',e=>{
 if(!modal)return;
 if(e.key==='Escape'){e.preventDefault();closeModal();return;}
 if(e.key!=='Tab')return;
 const dialog=document.querySelector('#modal');if(!dialog)return;
 const list=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')]
  .filter(node=>!node.hidden&&node.getClientRects().length&&getComputedStyle(node).visibility!=='hidden');
 if(!list.length)return;
 const first=list[0],last=list.at(-1);
 if(!list.includes(document.activeElement)){e.preventDefault();(e.shiftKey?last:first).focus();return;}
 if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
 else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
});
window.addEventListener('pageshow',()=>{if(catalog.length&&!modal)render();});
window.addEventListener('storage',e=>{if(e.key===Progress.LEARNER_KEY){if(modal)closeModal();showAll=false;filter='all';modeFilter='all';themeOffset=0;move('home');return;}if([Progress.KEY,Progress.LEGACY_KEY,Rewards.REWARDS_KEY,Progression.GOAL_KEY,VillageState.VILLAGE_KEY,RelationshipState.RELATIONSHIP_KEY,EcologyState.ECOLOGY_KEY,CloudSync.SESSION_KEY,CloudSync.CLOUD_STATE_KEY].includes(e.key)&&!modal)render();});
